{"file_path":"src/pointer.js","content":"/** JSON Pointer parsing, formatting and resolution over JSON data. */

/** Failure raised while parsing or resolving a pointer. */
export class PointerError extends Error {
  /**
   * @param {string} message reason, including the pointer position when known
   * @param {unknown} [pointer] the pointer the failure came from
   */
  constructor(message, pointer) {
    super(message);
    this.name = 'PointerError';
    this.pointer = pointer;
  }
}

/**
 * The JSON type name of a value, using 'null' and 'array' for those special cases.
 *
 * @param {unknown} value any value
 * @returns {string} a human-readable type name
 */
export function typeName(value) {
  if (value === null) return 'null';
  if (Array.isArray(value)) return 'array';
  return typeof value;
}

/**
 * Decode a single reference token's `~1`/`~0` escapes in one left-to-right pass.
 *
 * @param {string} token the raw (still-escaped) token text
 * @returns {string} the decoded token
 */
function decodeToken(token) {
  let result = '';
  for (let i = 0; i < token.length; i += 1) {
    const char = token[i];
    if (char !== '~') {
      result += char;
      continue;
    }
    const next = token[i + 1];
    if (next === '0') {
      result += '~';
      i += 1;
    } else if (next === '1') {
      result += '/';
      i += 1;
    } else {
      throw new PointerError(`invalid escape in pointer token: ~${next ?? ''}`);
    }
  }
  return result;
}

/**
 * Encode a single reference token's `~`/`/` characters.
 *
 * @param {string} token the decoded token text
 * @returns {string} the escaped token
 */
function encodeToken(token) {
  return token.split('~').join('~0').split('/').join('~1');
}

/**
 * Split a pointer into decoded reference tokens.
 *
 * @param {string} pointer JSON Pointer text
 * @returns {string[]} the decoded tokens, empty for the whole-document pointer
 */
export function parsePointer(pointer) {
  if (typeof pointer !== 'string') throw new Error('pointer must be a string');
  if (pointer === '') return [];
  if (pointer[0] !== '/') throw new PointerError("pointer must be empty or start with '/'", pointer);
  return pointer
    .slice(1)
    .split('/')
    .map((token) => decodeToken(token));
}

/**
 * Join reference tokens into a pointer.
 *
 * @param {string[]} tokens reference tokens
 * @returns {string} the pointer text, empty for no tokens
 */
export function formatPointer(tokens) {
  if (!Array.isArray(tokens)) throw new Error('tokens must be an array');
  for (const token of tokens) {
    if (typeof token !== 'string') throw new Error('reference token must be a string');
  }
  return tokens.map((token) => `/${encodeToken(token)}`).join('');
}

/**
 * Step one reference token into a container.
 *
 * @param {unknown} current the container being indexed
 * @param {string} token the decoded reference token
 * @param {string} path the pointer up to and including this token, for error messages
 * @returns {unknown} the value the token selects
 */
export function stepInto(current, token, path) {
  if (Array.isArray(current)) {
    if (!/^(0|[1-9][0-9]*)$/.test(token)) {
      throw new PointerError(`invalid array index: ${token} at ${path}`, path);
    }
    const index = Number(token);
    if (index >= current.length) {
      throw new PointerError(`index out of range: ${token} at ${path}`, path);
    }
    return current[index];
  }
  if (current !== null && typeof current === 'object') {
    if (!Object.prototype.hasOwnProperty.call(current, token)) {
      throw new PointerError(`missing property: ${token} at ${path}`, path);
    }
    return current[token];
  }
  throw new PointerError(`cannot index into ${typeName(current)} at ${path}`, path);
}

/**
 * Resolve a pointer against a document.
 *
 * @param {unknown} document JSON data to walk
 * @param {string} pointer JSON Pointer text
 * @returns {unknown} the value the pointer selects
 */
export function resolve(document, pointer) {
  const tokens = parsePointer(pointer);
  let current = document;
  const consumed = [];
  for (const token of tokens) {
    consumed.push(token);
    current = stepInto(current, token, formatPointer(consumed));
  }
  return current;
}
"}

